import { z } from "zod";

/**
 * High school data source types
 * Shared between students and search contracts to avoid circular dependencies
 */
export const highSchoolSourceSchema = z.enum([
  "PUBLIC",
  "PRIVATE",
  "NCES_CCD",
  "NCES_PSS",
  "OPENDATASOFT_PUBLIC",
  "OPENDATASOFT_PRIVATE",
  "URBAN_INSTITUTE",
]);

export type HighSchoolSource = z.infer<typeof highSchoolSourceSchema>;
